"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4748],{26169:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PetController","desc":"Renders every player\'s equipped pets on this client. The server publishes\\neach player\'s pet ids in their `EquippedPets` attribute (CosmeticService).\\nPets here are anchored, collision-free clones moved every frame, so they\\ncost the server nothing and never push anyone.\\n\\nGround pets trail their owner like a dog: they ease toward a formation\\nslot behind the owner, stand on the floor found by a raycast under that\\nslot, and hop while moving. Flying pets hover at the same slot with a slow\\nbob. Pets hide while their owner\'s character is in a round (`RoundTag`),\\nso they never give away where someone is hiding.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Client"],"source":{"line":19,"path":"src/Client/Features/Market/Controllers/PetController.luau"}}')}}]);